    print(f"   {'treatment':<12}{'mean sharpe':>13}{'sd':>8}{'p05':>8}{'p95':>8}"
          f"{'beats vintage':>16}")
    for name in ("vintage", "revised", "ref-date"):
        r = sw.loc[name]
        print(f"   {name:<12}{r['mean']:>13.3f}{r['sd']:>8.3f}{r['p05']:>8.3f}"
              f"{r['p95']:>8.3f}{r['beats_vintage']:>16.1%}")
    print(f"   The single-seed row above is one draw from these distributions; the gap is")
    print(f"   a property of the design, the level is not.")

    print("\n" + "=" * 78)
    print("5. Which look-ahead actually costs you: mean Sharpe gap over vintage")
    print("=" * 78)
    rev, ref = gap_grid()
    print("   rows = revision size as a multiple of BLS's own payroll numbers")
    print("   cols = momentum window in months (1 = compare with last month's print)")
    print("   60 seeds x 480 months per cell.\n")
    for title, tabx in (("revised values, right reference month", rev),
                        ("reference-date join (values AND timing)", ref)):
        print(f"   {title}")
        print(f"   {'':<8}" + "".join(f"{c:>10}" for c in tabx.columns))
        for i in tabx.index:
            print(f"   {i:<8}" + "".join(f"{tabx.loc[i, c]:>10.3f}" for c in tabx.columns))
        print()
    print("   The two bugs have different signatures, and that is the diagnostic:")
    print("   the VALUE gap rises monotonically with the size of the revisions at every")
    print("   window - 4x the revisions, 3.6x to 7x the gap. The TIMING gap barely moves with")
    print("   revision size at all, because it is not a data-quality problem: it is a")
    print("   month of the future, and it is the larger of the two at every window past 1.")
    print("   At payrolls' own revision size the value look-ahead is worth 0.02-0.05 of")
    print("   Sharpe. Do not expect the A/B to fail loudly on revisions alone.")

    print(f"\n   (total runtime {time.time() - t0:.1f}s)")
    print("\nRule: run the strategy twice - once on today's series and once on the vintage"
          " available at each decision date - and report both Sharpes; if you cannot build"
          " the second one, you do not have a result.")
